function PlayerController.prototype.moveCameraToFightPoint(self)
    y3.timer.wait(
        2.5,
        function()
            for ____, playerId in ipairs(playerIdList) do
                local unitData = writeableDatas.players[playerId]:getOrCreateSingle(UnitData)
                local pos = y3.point.get_point_by_res_id(mapConfig.playerPoints[playerId])
                local time = 1.2
                local currentCameraPos = y3.camera.get_camera_center_raycast(LOCAL.PLAYER)
                local x = currentCameraPos:get_x() - unitData.origin_position:get_x()
                local y = currentCameraPos:get_y() - unitData.origin_position:get_y()
                local offset = math.sqrt(x * x + y * y)
                if offset > 3200 then
                    cameraController:lookAt(
                        playerId,
                        unitData.origin_position:get_x(),
                        unitData.origin_position:get_y(),
                        0
                    )
                    y3.timer.wait_frame(
                        1,
                        function()
                            cameraController:lookAt(
                                playerId,
                                pos:get_x(),
                                pos:get_y() - 1450,
                                time
                            )
                        end
                    )
                else
                    cameraController:lookAt(
                        playerId,
                        pos:get_x(),
                        pos:get_y() - 1450,
                        time
                    )
                end
            end
        end
    )
