function PlayerController.prototype.killMercenary(self, killerId, belongId, gold, unit, wood)
    if wood == nil then
        wood = 0
    end
    if killerId == belongId or killerId == PlayerId.LEFT_KING or killerId == PlayerId.RIGHT_KING then
        if killerId == PlayerId.LEFT_KING or killerId == PlayerId.RIGHT_KING then
            local kingData = writeableDatas.players[killerId]:getOrCreateSingle(KingData)
            local king = __TS__ArrayFind(
                writeableDatas.players[killerId]:getAll(UnitData),
                function(____, a) return a.id == kingData.currentUnit end
            )
            local ____opt_52 = king.entity.y3Unit
            if (____opt_52 and ____opt_52:get_hp()) == 0 then
                return
            end
        end
        playerDataController:addGold(killerId, gold)
        playerDataController:addWood(killerId, wood)
        effectController:showGold(killerId, unit, gold)
        if wood ~= 0 then
            effectController:showGold(killerId, unit, wood)
        end
    else
        local gameData = writeableDatas.global:getOrCreateSingle(GameData)
        local levelCfg = levelConfigMap[gameData.level]
        local total = levelCfg.dividendRatio[1] + levelCfg.dividendRatio[2]
        local killer_gold = math.floor(gold * levelCfg.dividendRatio[2] / total)
        playerDataController:addGold(killerId, killer_gold)
        playerDataController:addGold(belongId, gold - killer_gold)
        effectController:showGold(killerId, unit, killer_gold)
        effectController:showGold(belongId, unit, gold - killer_gold)
    end
end
