    elseif #playerData.talent == 2 then
        entity:modifyValue(entity, _____5929_8D4B_2, id, true)
    elseif #playerData.talent == 3 then
        entity:modifyValue(entity, _____5929_8D4B_3, id, true)
    elseif #playerData.talent == 4 then
        entity:modifyValue(entity, _____5929_8D4B_4, config.id, true)
    end
    local quantities = {}
    local replacedEffectIds = {}
    local addIds = {}
    if #config.replaceEffectQuantity % 2 ~= 0 then
