        while i < #config.replaceEffectQuantity do
            replacedEffectIds[#replacedEffectIds + 1] = config.replaceEffectQuantity[i + 1].id
            quantities[#quantities + 1] = entity:getEffectQuantity(config.replaceEffectQuantity[i + 1].id)
            addIds[#addIds + 1] = config.replaceEffectQuantity[i + 1 + 1].id
            i = i + 2
        end
    end
    if #replacedEffectIds > 0 then
        entity:removeEffect(entity, replacedEffectIds)
    end
    entity:removeEffect(
        entity,
        __TS__ArrayMap(
            config.removeEffects,
            function(____, a) return a.id end
        )
    )
    __TS__ArrayForEach(
        config.newEffects,
        function(____, a)
            entity:addEffect(entity, a.id, nil)
        end
    )
    do
        local i = 0
        while i < #addIds do
            entity:addEffect(entity, addIds[i + 1], quantities[i + 1])
            i = i + 1
        end
    end
    if config.addSimpleSkill ~= nil then
